import { db } from '@/lib/db';

const MAX_CACHED_CLIPS = 50;

/**
 * Computes deterministic SHA-256 hex string for a given text and voiceId.
 * Normalized to lowercase and trimmed to maximize cache hits.
 */
export async function computeSpeechHash(
  text: string,
  voiceId: string = 'nature-narrator'
): Promise<string> {
  const normalized = `${voiceId}:${text.trim().toLowerCase()}`;
  if (typeof crypto !== 'undefined' && crypto.subtle) {
    const encoder = new TextEncoder();
    const data = encoder.encode(normalized);
    const hashBuffer = await crypto.subtle.digest('SHA-256', data);
    const hashArray = Array.from(new Uint8Array(hashBuffer));
    return hashArray.map((b) => b.toString(16).padStart(2, '0')).join('');
  }

  // Node.js fallback for test runner
  const nodeCrypto = await import('crypto');
  return nodeCrypto.createHash('sha256').update(normalized).digest('hex');
}

/**
 * Checks Dexie speechCache for existing synthesized audio blob.
 */
export async function getCachedSpeech(textHash: string): Promise<Blob | null> {
  try {
    const record = await db.speechCache.where('textHash').equals(textHash).first();
    if (!record || !record.audio) return null;

    if (record.audio instanceof Blob) {
      return record.audio;
    } else if (typeof record.audio === 'string') {
      // Base64 or object URL fallback
      const buffer = Buffer.from(record.audio, 'base64');
      return new Blob([buffer], { type: 'audio/mpeg' });
    }
    return null;
  } catch (err) {
    console.warn('Error reading speechCache:', err);
    return null;
  }
}

/**
 * Saves synthesized audio blob in Dexie speechCache and applies LRU eviction (max 50 clips).
 */
export async function saveCachedSpeech(
  textHash: string,
  audio: Blob
): Promise<void> {
  try {
    const existing = await db.speechCache.where('textHash').equals(textHash).first();
    if (existing) return;

    await db.speechCache.add({
      id: crypto.randomUUID(),
      textHash,
      audio,
      createdAt: Date.now(),
    });

    // Enforce LRU pruning if count exceeds threshold
    const totalCount = await db.speechCache.count();
    if (totalCount > MAX_CACHED_CLIPS) {
      const oldest = await db.speechCache
        .orderBy('createdAt')
        .limit(totalCount - MAX_CACHED_CLIPS)
        .toArray();

      for (const item of oldest) {
        await db.speechCache.delete(item.id);
      }
    }
  } catch (err) {
    console.warn('Error saving to speechCache:', err);
  }
}

/**
 * Native browser SpeechSynthesis fallback with sentence-level stability.
 */
export function speakWithBrowserUtterance(
  text: string,
  options?: {
    rate?: number;
    onEnd?: () => void;
    onError?: (err: any) => void;
  }
): void {
  if (typeof window === 'undefined' || !window.speechSynthesis) {
    options?.onError?.(new Error('speechSynthesis not supported on this device'));
    return;
  }

  try {
    window.speechSynthesis.cancel(); // Stop any pending speech

    const utterance = new SpeechSynthesisUtterance(text);
    utterance.rate = options?.rate || 1.0;
    utterance.pitch = 1.0;
    utterance.lang = 'en-US';

    // Pick a natural English voice if available
    const voices = window.speechSynthesis.getVoices();
    const naturalVoice = voices.find(
      (v) =>
        v.lang.startsWith('en') &&
        (v.name.includes('Natural') ||
          v.name.includes('Google') ||
          v.name.includes('Samantha') ||
          v.name.includes('Daniel'))
    );
    if (naturalVoice) {
      utterance.voice = naturalVoice;
    }

    utterance.onend = () => {
      options?.onEnd?.();
    };

    utterance.onerror = (err) => {
      console.warn('speechSynthesis utterance error:', err);
      options?.onError?.(err);
    };

    window.speechSynthesis.speak(utterance);
  } catch (err) {
    console.warn('Failed to start browser speech synthesis:', err);
    options?.onError?.(err);
  }
}

export function stopBrowserUtterance(): void {
  if (typeof window !== 'undefined' && window.speechSynthesis) {
    try {
      window.speechSynthesis.cancel();
    } catch {}
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { checkRateLimit } from '@/lib/rate-limit';

const DEFAULT_NATURE_VOICE_ID = '21m00Tcm4TlvDq8ikWAM'; // Rachel (warm, calm narrator)

export async function POST(req: NextRequest) {
  // 1. Rate limiting check (40 calls / day)
  const rateLimit = await checkRateLimit(req, 'speak');
  if (!rateLimit.success) {
    return NextResponse.json(
      { error: 'Rate limit exceeded for speech narration. Try again later.' },
      { status: 429, headers: rateLimit.headers }
    );
  }

  try {
    const body = await req.json();
    const { text, voiceId = DEFAULT_NATURE_VOICE_ID } = body;

    if (!text || typeof text !== 'string') {
      return NextResponse.json(
        { error: 'Missing or invalid text parameter' },
        { status: 400, headers: rateLimit.headers }
      );
    }

    const apiKey = process.env.ELEVENLABS_API_KEY;

    // 2. Stream audio from ElevenLabs TTS if key is present
    if (apiKey) {
      const elevenRes = await fetch(
        `https://api.elevenlabs.io/v1/text-to-speech/${voiceId}`,
        {
          method: 'POST',
          headers: {
            'xi-api-key': apiKey,
            'Content-Type': 'application/json',
            Accept: 'audio/mpeg',
          },
          body: JSON.stringify({
            text: text.slice(0, 2000), // Cap length for safety
            model_id: 'eleven_multilingual_v2',
            voice_settings: {
              stability: 0.55,
              similarity_boost: 0.75,
            },
          }),
        }
      );

      if (elevenRes.ok && elevenRes.body) {
        return new Response(elevenRes.body, {
          status: 200,
          headers: {
            'Content-Type': 'audio/mpeg',
            'Cache-Control': 'public, max-age=86400',
            ...rateLimit.headers,
          },
        });
      } else {
        console.warn(
          'ElevenLabs TTS API error:',
          elevenRes.status,
          await elevenRes.text()
        );
      }
    }

    // 3. Graceful fallback when key is absent or API returned error
    return NextResponse.json(
      {
        fallback: true,
        message:
          'ELEVENLABS_API_KEY not configured or unavailable. Client should use browser speechSynthesis.',
      },
      { status: 200, headers: rateLimit.headers }
    );
  } catch (err: any) {
    console.error('Speech narration route error:', err);
    return NextResponse.json(
      { error: err.message || 'Internal speech narration error' },
      { status: 500, headers: rateLimit.headers }
    );
  }
}

import { POST } from '../app/api/speak/route';
import { NextRequest } from 'next/server';
import { computeSpeechHash } from '../lib/speech';

async function runTests() {
  console.log('Testing /api/speak Route & Speech Utilities...');

  // 1. SHA-256 Text Hash determinism
  console.log('\n--- 1. Testing SHA-256 Speech Hash Determinism ---');
  const textA = 'European Robin is a small insectivorous passerine bird.';
  const hash1 = await computeSpeechHash(textA, 'rachel');
  const hash2 = await computeSpeechHash(textA.toUpperCase(), 'rachel');
  const hash3 = await computeSpeechHash(textA, 'daniel');

  console.log('Hash 1:', hash1);
  console.log('Hash 2 (case-insensitive):', hash2);
  console.log('Hash 3 (different voice):', hash3);

  if (hash1 !== hash2) {
    throw new Error('Expected normalized text hashes to match!');
  }
  if (hash1 === hash3) {
    throw new Error('Expected different voices to produce distinct hashes!');
  }
  console.log('✓ SHA-256 speech hashing is deterministic and normalized.');

  // 2. Missing text parameter -> 400
  console.log('\n--- 2. Testing missing text rejection ---');
  const req1 = new NextRequest('http://localhost:3000/api/speak', {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({}),
  });
  const res1 = await POST(req1);
  const data1 = await res1.json();
  console.log('Status:', res1.status, 'Response:', data1);
  if (res1.status !== 400 || !data1.error) {
    throw new Error('Expected 400 when text is missing!');
  }
  console.log('✓ Missing text rejected with 400.');

  // 3. Fallback response when ELEVENLABS_API_KEY is unset
  console.log('\n--- 3. Testing /api/speak response ---');
  const req2 = new NextRequest('http://localhost:3000/api/speak', {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({
      text: 'Robin is a small bird known for its red breast.',
    }),
  });
  const res2 = await POST(req2);
  console.log('Status:', res2.status, 'Content-Type:', res2.headers.get('content-type'));

  if (res2.status === 200) {
    const contentType = res2.headers.get('content-type') || '';
    if (contentType.includes('audio/mpeg')) {
      console.log('✓ Received ElevenLabs MP3 audio stream.');
    } else {
      const data2 = await res2.json();
      console.log('Fallback response:', data2);
      if (!data2.fallback) {
        throw new Error('Expected fallback flag in json response when key is missing!');
      }
      console.log('✓ Received valid fallback flag for client speechSynthesis.');
    }
  } else {
    throw new Error(`Unexpected status code: ${res2.status}`);
  }

  // 4. Rate limiting headers check
  console.log('\n--- 4. Testing Rate Limit Headers ---');
  const limitHeader = res2.headers.get('X-RateLimit-Limit');
  const remainingHeader = res2.headers.get('X-RateLimit-Remaining');
  console.log(`X-RateLimit-Limit: ${limitHeader}, X-RateLimit-Remaining: ${remainingHeader}`);
  if (!limitHeader) {
    throw new Error('Missing X-RateLimit-Limit header in response!');
  }
  console.log('✓ Rate limit headers verified.');

  console.log('\nAll /api/speak tests passed successfully!');
}

runTests().catch((err) => {
  console.error('Test execution failed:', err);
  process.exit(1);
});

